  boards_trace_begin();
  board_late_initialize();
  boards_trace_end();
#endif

#ifndef CONFIG_BOARD_CRASHDUMP_NONE
  coredump_initialize();
#endif

  posix_spawnattr_init(&attr);
  attr.priority  = CONFIG_INIT_PRIORITY;
  attr.stacksize = CONFIG_INIT_STACKSIZE;

